/*B"H — one panel, one clear control */
.panel-topbar {
  min-height: 48px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 0 12px;
  border-bottom: 1px solid var(--ai-border);
  background:
    linear-gradient(90deg, rgba(31,111,235,.34), rgba(47,240,160,.13)),
    radial-gradient(circle at 0 0, rgba(126,212,255,.20), transparent 42%);
  user-select: none;
  cursor: default;
  overflow: hidden;
}
.panel-title {
  font-weight: 950;
  letter-spacing: .012em;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-shadow: 0 1px 16px rgba(126,212,255,.18);
}
.panel-actions {
  display: inline-flex;
  gap: 0;
  flex: 0 0 auto;
  padding: 0;
  border-radius: 14px;
  background: transparent;
}
.panel-actions button {
  width: 34px;
  height: 34px;
  border-radius: 12px;
  border: 1px solid var(--ai-border);
  background: rgba(2,8,16,.88);
  color: var(--ai-text);
  cursor: pointer;
  line-height: 1;
  font-weight: 900;
}
.panel-actions button:hover {
  transform: translateY(-1px);
  border-color: var(--ai-border-hot);
  background: rgba(10, 28, 48, .94);
  box-shadow: 0 0 0 3px rgba(126,212,255,.08);
}

geelooy/ai/css/panels/collapsed.css.content:
/*B"H — collapsed rails cannot overlap: only one full-rail expander */
.is-collapsed,
.is-detached {
  min-width: 62px !important;
  width: auto !important;
  max-width: 100% !important;
  overflow: hidden !important;
}
.is-collapsed > :not(.panel-topbar),
.is-detached > :not(.panel-topbar) { display: none !important; }
.is-collapsed .panel-topbar,
.is-detached .panel-topbar {
  height: 100%;
  min-height: 0;
  display: grid;
  grid-template-rows: minmax(0, 1fr) 44px;
  grid-template-columns: 1fr;
  align-items: center;
  justify-items: center;
  gap: 8px;
  padding: 8px 6px;
  border-bottom: 0;
  cursor: pointer;
  outline: none;
}
.is-collapsed .panel-title,
.is-detached .panel-title {
  display: block;
  writing-mode: vertical-rl;
  text-orientation: mixed;
  max-height: 100%;
  max-width: 100%;
  overflow: hidden;
  white-space: nowrap;
  font-size: .8rem;
  opacity: .9;
}
.is-collapsed .panel-actions,
.is-detached .panel-actions {
  grid-row: 2;
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
}
.is-collapsed .panel-actions button,
.is-detached .panel-actions button {
  width: 38px;
  height: 38px;
  border-radius: 14px;
}
.is-collapsed .panel-topbar:hover,
.is-detached .panel-topbar:hover,
.is-collapsed .panel-topbar:focus-visible,
.is-detached .panel-topbar:focus-visible {
  box-shadow: inset 0 0 0 2px var(--ai-border-hot), 0 0 28px rgba(45, 212, 255, .18);
}
.is-detached {
  position: relative !important;
  z-index: auto !important;
  resize: none !important;
}

