/* B"H */
/*
  Chapter 10: The Cockpit Became a Crown of Moving Glass.
  Headers stay fixed, bodies scroll, panels expand like palaces, and the
  composer grows with the living word instead of choking beneath it.
*/
#automation-panel {
  display: flex;
  flex-direction: column;
  min-height: 0;
}
#automation-panel .right-tabs {
  flex: 0 0 auto;
  overflow: visible !important;
  overflow: visible !important;
  position: sticky;
  top: 0;
  z-index: 4;
  background: linear-gradient(180deg, rgba(8,47,73,.96), rgba(2,8,23,.86));
  border-bottom: 1px solid rgba(125,211,252,.18);
}
#automation-panel .right-panel-body {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  scrollbar-width: thin;
}
.input-area {
  align-items: flex-end;
  gap: 10px;
  padding: 10px;
  border: 1px solid rgba(125,211,252,.14);
  border-radius: 20px;
  background: linear-gradient(135deg, rgba(2,6,23,.88), rgba(8,47,73,.34));
