  line-height: 1.45;
  transition: height .12s ease, border-color .16s ease, box-shadow .16s ease;
}
#message-input:focus {
  border-color: rgba(34,211,238,.7);
  box-shadow: 0 0 0 3px rgba(34,211,238,.12);
}
.event-title-wrap {
  display: inline-flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.event-talked-to {
  color: rgba(203,241,255,.68);
  font-size: .78rem;
  font-weight: 700;
}
.event-panel-actions {
  margin-left: auto;
  display: inline-flex;
  gap: 6px;
}
.event-panel-actions button {
  width: 26px;
  height: 24px;
  border: 1px solid rgba(125,211,252,.18);
  border-radius: 9px;
  color: #dffaff;
  background: rgba(15,23,42,.72);
