}
.event-panel-actions button:hover {
  background: rgba(34,211,238,.22);
}
.transport-details.is-maximized,
.thought-envelope-card.is-maximized {
  width: min(980px, 100%);
  max-width: 100%;
}
.transport-details.is-fullscreen,
.thought-envelope-card.is-fullscreen {
  position: fixed;
  inset: 16px;
  z-index: 2147483000;
  max-width: none;
  background: #020817;
  border: 1px solid rgba(34,211,238,.45);
  border-radius: 22px;
  box-shadow: 0 30px 120px rgba(0,0,0,.72);
  overflow: auto;
}
.event-raw-lazy {
  margin: 10px;
  border-top: 1px solid rgba(151,205,255,.1);
}
.event-raw-lazy > summary {
  cursor: pointer;
  color: #a5f3fc;
  padding: 10px 0;
}
.event-link-panel a {
  display: inline-flex;
  max-width: 100%;
  overflow-wrap: anywhere;
  word-break: break-word;
}
